#!/usr/bin/env python3

from PIL import Image
from raztec import AztecCodeBuilder


def generate(data: str, error_correction: int = 23):
   builder = AztecCodeBuilder()
   builder.error_correction(error_correction)
   builder.append(data)
   return builder.build()


def image(builder, filename: str, modul_size: int = 10):
  pixels = code.to_mono8(module_size)
  img_size = code.size() * module_size
  img = Image.frombytes("L", (img_size, img_size), bytes(pixels))
  img.save(filename)


if "__name__" == "__main__":
  print("start generating")
  data = """"""
  code = generate(data)
  image(builder=code, filename="aztec.png", module_size=4)
  print("finish")

